const fs = require('fs');
const crypto = require('crypto');
const {LspConnection} = require(process.cwd() + '/editors/vscode/protocol');
const binaries = {baseline: process.argv[2], candidate: process.argv[3]};
const sources = {
  sieve: fs.readFileSync('test/benchmarks/sieve.tap', 'utf8'),
  extension_types: Array.from({length: 128}, (_,i) =>
    `let flags_${i} = bytes::buffer(8, 1)\nlet count_${i} = count(copy(flags_${i}), 1)\n`).join(''),
};
const rows = Object.entries(sources).map(([name,source]) => ({name,source,rounds:[]}));
async function measure(binary, row) {
  const c = new LspConnection(binary);
  const uri = 'file:///tmp/tapas-cleanup-lsp.tap';
  let receive;
  c.onNotification('textDocument/publishDiagnostics', value => {
    if(value.uri === uri && receive) {const done=receive;receive=null;done(value);}
  });
  await c.start();
  try {
    await c.request('initialize', {processId:process.pid,rootUri:'file://' + process.cwd(),capabilities:{}});
    c.notify('initialized',{});
    const samples=[];
    for(let i=0;i<40;i++) {
      let timer;
      const response=new Promise((resolve,reject) => {
        receive=resolve;
        timer=setTimeout(()=>reject(Error('diagnostic timeout')),10000);
      });
      const started=process.hrtime.bigint();
      const text=row.source+'\n// version '+i+'\n';
      if(i===0)c.notify('textDocument/didOpen',{textDocument:{uri,languageId:'tapas',version:i+1,text}});
      else c.notify('textDocument/didChange',{textDocument:{uri,version:i+1},contentChanges:[{text}]});
      const result=await response;clearTimeout(timer);
      if(result.diagnostics.length)throw Error(JSON.stringify(result.diagnostics));
      if(i>=8)samples.push(Number(process.hrtime.bigint()-started));
    }
    return samples;
  } finally {await c.stop();}
}
(async()=>{
 for(let round=0;round<3;round++) {
  for(const row of rows) {
   const samples={};
   for(const label of round%2?['candidate','baseline']:['baseline','candidate'])
     samples[label]=await measure(binaries[label],row);
   row.rounds.push(samples);
  }
 }
 const metadata=Object.fromEntries(Object.entries(binaries).map(([label,path])=>[label,{path,sha256:crypto.createHash('sha256').update(fs.readFileSync(path)).digest('hex')}]));
 const report={date:new Date().toISOString(),...metadata,method:'3 rounds; fresh server per case and runtime; 8 warm-up edits then 32 measured edits; full-text updates; wall time to diagnostics; alternating first runtime each round',rows,harness:fs.readFileSync(__filename,'utf8')};
 fs.writeFileSync(process.argv[4],JSON.stringify(report,null,2)+'\n');
})().catch(error=>{console.error(error);process.exitCode=1});
